    result = []
    for rr in range(h_out):
        row = []
        for cc in range(w_out):
            block_result = analyze_3x3_block(inp, rr, cc)

            output_val = 0

            # Rule revision:
            # 5 is background - don't treat single 5s as meaningful
            # Look for: (1) uniform non-5 value, OR (2) exactly one unique non-5 non-0 value

            if block_result['uniform']:
                val = list(block_result['values'])[0]
                if val != 0 and val != 5:
                    output_val = val
            elif block_result['has_unique'] and block_result['unique_value'] is not None:
                u = block_result['unique_value']
                if u != 0 and u != 5:
                    output_val = u

            row.append(output_val)
        result.append(row)

    return result

